from pathlib import Path
import json, sys
root = Path(sys.argv[1])
p = root/'app/nexora-app.tsx'
s = p.read_text()

def rep(old,new,label):
    global s
    if old not in s:
        raise SystemExit(f'missing block: {label}')
    s=s.replace(old,new,1)

rep('type ServerConfig = { id: ServerId; short: string; title: string; subtitle: string; className: string; defaultChannel: string; channels: Channel[]; members: Member[] };',
'''type ServerConfig = { id: ServerId; short: string; title: string; subtitle: string; className: string; defaultChannel: string; channels: Channel[]; members: Member[] };\ntype NetworkMessage = Message & { channelId: string; serverId: ServerId };\ntype NetworkReaction = { channelId: string; messageId: string; emoji: string };''','types')

rep('const createLocalId = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;',
'''const createLocalId = (prefix: string) => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;\nconst REALTIME_CONFIG = { appId: "klyvro-public-p2p-v2" };\nconst REALTIME_ROOM = "community-main";\n\nconst validNetworkMessage = (value: unknown): value is NetworkMessage => {\n  if (!value || typeof value !== "object") return false;\n  const item = value as Partial<NetworkMessage>;\n  return typeof item.id === "string" && item.id.length <= 100\n    && typeof item.author === "string" && item.author.length <= 24\n    && typeof item.text === "string" && item.text.length > 0 && item.text.length <= MAX_MESSAGE_LENGTH\n    && typeof item.channelId === "string" && item.channelId.length <= 40\n    && (item.serverId === "kv" || item.serverId === "cp" || item.serverId === "mc");\n};\n\nconst mergeMessages = (current: Message[], incoming: Message[]) => {\n  const byId = new Map(current.map((message) => [message.id, message]));\n  for (const message of incoming) {\n    const existing = byId.get(message.id);\n    if (!existing) byId.set(message.id, { ...message, avatarUrl: null });\n    else if (message.reactions) {\n      const reactions = { ...existing.reactions };\n      for (const [emoji, count] of Object.entries(message.reactions)) reactions[emoji] = Math.max(reactions[emoji] ?? 0, count);\n      byId.set(message.id, { ...existing, reactions });\n    }\n  }\n  return Array.from(byId.values()).slice(-150);\n};\n\nconst historySnapshot = (source: Record<string, Message[]>) => Object.fromEntries(\n  Object.entries(source).map(([channelId, items]) => [channelId, items.slice(-100).map((message) => ({ ...message, avatarUrl: null }))]),\n);''','helpers')

rep('  const [storageReady, setStorageReady] = useState(false);',
'''  const [storageReady, setStorageReady] = useState(false);\n  const [chatPeers, setChatPeers] = useState(0);\n  const [networkState, setNetworkState] = useState<"connecting" | "online" | "offline">("connecting");''','states')

rep('  const floatingTriggerRef = useRef<HTMLButtonElement | null>(null);',
'''  const floatingTriggerRef = useRef<HTMLButtonElement | null>(null);\n  const messagesRef = useRef<Record<string, Message[]>>(initialMessages);\n  const messageSendRef = useRef<((message: NetworkMessage) => Promise<unknown>) | null>(null);\n  const reactionSendRef = useRef<((reaction: NetworkReaction) => Promise<unknown>) | null>(null);\n  const selectedRef = useRef(selected);''','refs')

needle='  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(null), 2600); return () => window.clearTimeout(timer); }, [toast]);'
insert=needle+'''\n\n  useEffect(() => { messagesRef.current = messages; }, [messages]);\n  useEffect(() => { selectedRef.current = selected; }, [selected]);\n\n  useEffect(() => {\n    if (!storageReady) return;\n    let cancelled = false;\n    let leaveRoom: (() => void) | null = null;\n    setNetworkState("connecting");\n\n    void (async () => {\n      try {\n        const { joinRoom } = await import("trystero");\n        if (cancelled) return;\n        const room = joinRoom(REALTIME_CONFIG, REALTIME_ROOM, {\n          onJoinError: () => { if (!cancelled) setNetworkState("offline"); },\n        });\n        leaveRoom = () => room.leave();\n        const messageAction = room.makeAction<NetworkMessage>("message-v2");\n        const historyAction = room.makeAction<Record<string, Message[]>>("history-v2");\n        const reactionAction = room.makeAction<NetworkReaction>("reaction-v2");\n        const updatePeerCount = () => setChatPeers(Object.keys(room.getPeers()).length);\n\n        messageSendRef.current = (message) => messageAction.send(message);\n        reactionSendRef.current = (reaction) => reactionAction.send(reaction);\n\n        room.onPeerJoin = (peerId) => {\n          updatePeerCount();\n          void historyAction.send(historySnapshot(messagesRef.current), { target: peerId });\n        };\n        room.onPeerLeave = () => updatePeerCount();\n\n        messageAction.onMessage = (incoming) => {\n          if (!validNetworkMessage(incoming)) return;\n          setMessages((previous) => {\n            const updated = { ...previous, [incoming.channelId]: mergeMessages(previous[incoming.channelId] ?? [], [{ ...incoming, avatarUrl: null }]) };\n            writeLocal(STORAGE_KEYS.messages, updated);\n            messagesRef.current = updated;\n            return updated;\n          });\n          if (incoming.channelId !== selectedRef.current) setReadChannels((current) => ({ ...current, [incoming.channelId]: false }));\n        };\n\n        historyAction.onMessage = (incoming) => {\n          if (!incoming || typeof incoming !== "object") return;\n          setMessages((previous) => {\n            const updated = { ...previous };\n            for (const [channelId, items] of Object.entries(incoming).slice(0, 20)) {\n              if (!Array.isArray(items)) continue;\n              const safe = items.slice(-100).filter((item): item is Message => {\n                if (!item || typeof item !== "object") return false;\n                const candidate = item as Partial<Message>;\n                return typeof candidate.id === "string" && typeof candidate.author === "string" && typeof candidate.text === "string" && candidate.text.length <= MAX_MESSAGE_LENGTH;\n              }).map((item) => ({ ...item, avatarUrl: null }));\n              updated[channelId] = mergeMessages(updated[channelId] ?? [], safe);\n            }\n            writeLocal(STORAGE_KEYS.messages, updated);\n            messagesRef.current = updated;\n            return updated;\n          });\n        };\n\n        reactionAction.onMessage = (incoming) => {\n          if (!incoming || typeof incoming.channelId !== "string" || typeof incoming.messageId !== "string" || typeof incoming.emoji !== "string") return;\n          setMessages((previous) => {\n            const updated = { ...previous, [incoming.channelId]: (previous[incoming.channelId] ?? []).map((message) => message.id === incoming.messageId ? { ...message, reactions: { ...message.reactions, [incoming.emoji]: (message.reactions?.[incoming.emoji] ?? 0) + 1 } } : message) };\n            writeLocal(STORAGE_KEYS.messages, updated);\n            messagesRef.current = updated;\n            return updated;\n          });\n        };\n\n        updatePeerCount();\n        setNetworkState("online");\n      } catch {\n        if (!cancelled) { setChatPeers(0); setNetworkState("offline"); }\n      }\n    })();\n\n    return () => {\n      cancelled = true;\n      messageSendRef.current = null;\n      reactionSendRef.current = null;\n      leaveRoom?.();\n    };\n  }, [storageReady]);'''
rep(needle,insert,'realtime effect')

rep('    setToast("Mensagem enviada neste dispositivo");',
'''    const networkMessage: NetworkMessage = { ...next, avatarUrl: null, channelId: selected, serverId: activeServer };\n    void messageSendRef.current?.(networkMessage).catch(() => setNetworkState("offline"));\n    setToast(networkState === "online" ? (chatPeers > 0 ? `Mensagem enviada para ${chatPeers} conectado${chatPeers === 1 ? "" : "s"}` : "Mensagem publicada. Aguardando outros jogadores.") : "Mensagem salva localmente; rede P2P indisponível.");''','submit send')

old='''  const react = (id: string, emoji: string) => setMessages((previous) => {\n    const updated = { ...previous, [selected]: (previous[selected] ?? []).map((message) => message.id === id ? { ...message, reactions: { ...message.reactions, [emoji]: (message.reactions?.[emoji] ?? 0) + 1 } } : message) };\n    writeLocal(STORAGE_KEYS.messages, updated);\n    return updated;\n  });'''
new='''  const react = (id: string, emoji: string) => {\n    setMessages((previous) => {\n      const updated = { ...previous, [selected]: (previous[selected] ?? []).map((message) => message.id === id ? { ...message, reactions: { ...message.reactions, [emoji]: (message.reactions?.[emoji] ?? 0) + 1 } } : message) };\n      writeLocal(STORAGE_KEYS.messages, updated);\n      messagesRef.current = updated;\n      return updated;\n    });\n    void reactionSendRef.current?.({ channelId: selected, messageId: id, emoji }).catch(() => setNetworkState("offline"));\n  };'''
rep(old,new,'reaction')

rep('<VoiceRoom roomName={channel.label} profile={profile} audio={audio} onAudioChange={saveAudio} onToast={setToast} />',
    '<VoiceRoom roomName={channel.label} roomId={`${activeServer}:${channel.id}`} profile={profile} audio={audio} onAudioChange={saveAudio} onToast={setToast} />','voice props')

rep('<b><i /> 32 MS</b><b><Icon name="shield" size={12} /> PERFIL LOCAL</b>',
    '<b><i /> {chatPeers} PARES</b><b><Icon name="shield" size={12} /> WEBRTC</b>','banner')
rep('<span><Icon name="radio" size={12} /> Baixa latência</span><span><Icon name="shield" size={12} /> Dados locais</span>',
    '<span><Icon name="radio" size={12} /> P2P ao vivo</span><span><Icon name="shield" size={12} /> {chatPeers} conectado{chatPeers === 1 ? "" : "s"}</span>','chips')
rep('<div className="connection-card"><div><Icon name="radio" size={17} /><span>Klyvro Relay</span></div><strong>São Paulo • 32 ms</strong><div className="signal-bars"><i /><i /><i /><i /></div></div>',
    '<div className="connection-card"><div><Icon name="radio" size={17} /><span>Klyvro P2P</span></div><strong>{networkState === "online" ? `${chatPeers} navegador${chatPeers === 1 ? "" : "es"} conectado${chatPeers === 1 ? "" : "s"}` : networkState === "connecting" ? "Conectando à rede" : "Rede indisponível"}</strong><div className="signal-bars"><i /><i /><i /><i /></div></div>','connection card')

p.write_text(s)

pkg=root/'package.json'
data=json.loads(pkg.read_text())
data.setdefault('dependencies',{})['trystero']='^0.25.0'
pkg.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')

css=root/'app/polish.css'
css.write_text(css.read_text()+'''\n\n/* P2P realtime state */\n.voice-empty-live { width: min(260px, 80vw); min-height: 104px; padding: 16px; display: grid; justify-items: center; gap: 6px; border: 1px dashed var(--border-subtle); border-radius: 14px; color: var(--text-secondary); text-align: center; }\n.voice-empty-live svg { color: var(--accent); }\n.voice-empty-live strong { font-size: 13px; color: var(--text-normal); }\n.voice-empty-live span { max-width: 220px; font-size: 12px; line-height: 1.45; }\n''')
